"use client";

import Image from "next/image";
import { Camera, Check, LockKeyhole, Pencil, Trash2, X } from "lucide-react";
import { useRef, useState, type ChangeEvent, type FormEvent } from "react";

import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { toast } from "@/components/ui/toaster";

type ProfileUser = {
  id: string;
  name: string;
  email: string;
  role: "student" | "admin";
  tier: "UNIVERSITY" | "OTHER";
  roll: string | null;
  university: string | null;
  studentId: string | null;
  phone: string | null;
  avatarUrl: string | null;
  verified: boolean;
  createdAt: string;
  lastLoginAt: string | null;
};

type ApiResult<T> = {
  data?: T;
  error?: string;
};

export function ProfileClient({ user: initialUser }: { user: ProfileUser }) {
  const [user, setUser] = useState(initialUser);
  const [draft, setDraft] = useState({
    name: initialUser.name,
    phone: initialUser.phone ?? "",
  });
  const [editing, setEditing] = useState(false);
  const [saving, setSaving] = useState(false);
  const [uploading, setUploading] = useState(false);
  const [passwordOpen, setPasswordOpen] = useState(false);
  const [passwordSaving, setPasswordSaving] = useState(false);
  const [passwordError, setPasswordError] = useState("");
  const [passwords, setPasswords] = useState({
    currentPassword: "",
    newPassword: "",
    confirmPassword: "",
  });
  const fileInput = useRef<HTMLInputElement>(null);

  async function saveProfile(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    setSaving(true);

    try {
      const response = await fetch("/api/user/profile", {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          name: draft.name,
          phone: draft.phone,
        }),
      });
      const result = (await response.json()) as ApiResult<{
        user: Partial<ProfileUser>;
      }>;

      if (!response.ok || !result.data?.user) {
        throw new Error(result.error ?? "Unable to update your profile.");
      }

      setUser((current) => ({ ...current, ...result.data?.user }));
      setEditing(false);
      toast("Your profile has been updated.");
    } catch (error) {
      toast(getErrorMessage(error, "Unable to update your profile."), "error");
    } finally {
      setSaving(false);
    }
  }

  async function uploadAvatar(event: ChangeEvent<HTMLInputElement>) {
    const file = event.currentTarget.files?.[0];

    if (!file) {
      return;
    }

    setUploading(true);

    try {
      const formData = new FormData();
      formData.set("file", file);

      const response = await fetch("/api/user/avatar", {
        method: "POST",
        body: formData,
      });
      const result = (await response.json()) as ApiResult<{
        avatarUrl: string;
      }>;

      if (!response.ok || !result.data?.avatarUrl) {
        throw new Error(result.error ?? "Unable to upload your photo.");
      }

      setUser((current) => ({
        ...current,
        avatarUrl: result.data?.avatarUrl ?? null,
      }));
      toast("Your profile photo has been updated.");
    } catch (error) {
      toast(getErrorMessage(error, "Unable to upload your photo."), "error");
    } finally {
      setUploading(false);

      if (fileInput.current) {
        fileInput.current.value = "";
      }
    }
  }

  async function removeAvatar() {
    setUploading(true);

    try {
      const response = await fetch("/api/user/avatar", { method: "DELETE" });
      const result = (await response.json()) as ApiResult<unknown>;

      if (!response.ok) {
        throw new Error(result.error ?? "Unable to remove your photo.");
      }

      setUser((current) => ({ ...current, avatarUrl: null }));
      toast("Your profile photo has been removed.");
    } catch (error) {
      toast(getErrorMessage(error, "Unable to remove your photo."), "error");
    } finally {
      setUploading(false);
    }
  }

  async function changePassword(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    setPasswordError("");

    if (passwords.newPassword !== passwords.confirmPassword) {
      setPasswordError("The new passwords do not match.");
      return;
    }

    setPasswordSaving(true);

    try {
      const response = await fetch("/api/user/password", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          currentPassword: passwords.currentPassword,
          newPassword: passwords.newPassword,
        }),
      });
      const result = (await response.json()) as ApiResult<{
        message: string;
      }>;

      if (!response.ok) {
        throw new Error(result.error ?? "Unable to update your password.");
      }

      setPasswordOpen(false);
      setPasswords({
        currentPassword: "",
        newPassword: "",
        confirmPassword: "",
      });
      toast(result.data?.message ?? "Password updated.");
    } catch (error) {
      setPasswordError(
        getErrorMessage(error, "Unable to update your password."),
      );
    } finally {
      setPasswordSaving(false);
    }
  }

  const details = [
    { label: "Full name", value: user.name, key: "name" as const },
    { label: "Email", value: user.email },
    {
      label: "Phone",
      value: user.phone || "Not provided",
      key: "phone" as const,
    },
    { label: "Roll number", value: user.roll || "Not provided" },
    { label: "University", value: user.university || "Not provided" },
    { label: "Student ID", value: user.studentId || "Not provided" },
  ];

  return (
    <div className="mx-auto max-w-5xl">
      <header>
        <h1 className="font-heading text-2xl font-bold text-primary lg:text-3xl">
          Profile
        </h1>
        <p className="mt-1 text-sm text-muted">
          Manage your account details and preferences.
        </p>
      </header>

      <section className="mt-6 rounded-lg border border-border bg-card p-6 shadow-sm lg:p-8">
        <div className="flex flex-col gap-6 lg:flex-row lg:items-start">
          <div className="flex flex-col items-center gap-3">
            <AvatarDisplay avatarUrl={user.avatarUrl} name={user.name} />
            <label
              className="
                inline-flex min-h-10 cursor-pointer items-center gap-2 rounded-md
                border border-border px-4 text-sm font-medium text-primary
                focus-within:outline-none focus-within:ring-2
                focus-within:ring-accent focus-within:ring-offset-2
              "
            >
              <Camera size={16} />
              {uploading ? "Uploading" : "Upload photo"}
              <input
                ref={fileInput}
                type="file"
                accept="image/jpeg,image/png,image/webp"
                disabled={uploading}
                onChange={uploadAvatar}
                className="sr-only"
              />
            </label>
            {user.avatarUrl ? (
              <button
                type="button"
                disabled={uploading}
                onClick={removeAvatar}
                className="
                  inline-flex min-h-9 cursor-pointer items-center gap-2 px-3
                  text-sm text-muted hover:text-red-600 focus-visible:outline-none
                  focus-visible:ring-2 focus-visible:ring-accent
                  focus-visible:ring-offset-2 disabled:opacity-50
                "
              >
                <Trash2 size={15} />
                Remove photo
              </button>
            ) : null}
          </div>

          <div className="flex-1 text-center lg:text-left">
            <h2 className="font-heading text-2xl font-bold text-primary">
              {user.name}
            </h2>
            <p className="mt-1 text-sm text-muted">{user.email}</p>
            <div className="mt-3 flex flex-wrap justify-center gap-2 lg:justify-start">
              <Badge className="border-primary/20 text-primary">
                {user.tier === "UNIVERSITY"
                  ? "University student"
                  : "General student"}
              </Badge>
              <Badge
                className={
                  user.verified
                    ? "border-emerald-600/30 text-emerald-700"
                    : "border-amber-600/30 text-amber-700"
                }
              >
                {user.verified ? "Email verified" : "Email not verified"}
              </Badge>
            </div>
            <p className="mt-4 text-xs text-muted">
              Member since {formatDate(user.createdAt)}.
            </p>
          </div>
        </div>
      </section>

      <section className="mt-6 rounded-lg border border-border bg-card p-6 shadow-sm lg:p-8">
        <div className="flex items-center justify-between gap-4">
          <h2 className="font-heading text-lg font-bold text-primary">
            Personal information
          </h2>
          {!editing ? (
            <Button
              type="button"
              onClick={() => setEditing(true)}
              className="h-9 rounded-md bg-transparent px-3 text-primary hover:bg-primary/5"
            >
              <Pencil size={16} />
              Edit
            </Button>
          ) : null}
        </div>

        <form onSubmit={saveProfile}>
          <div className="mt-5 grid gap-4 sm:grid-cols-2">
            {details.map((detail) => (
              <div key={detail.label} className="space-y-2">
                <Label
                  htmlFor={`profile-${detail.label}`}
                  className="text-xs font-semibold uppercase tracking-wide text-muted"
                >
                  {detail.label}
                </Label>
                {editing && detail.key ? (
                  <Input
                    id={`profile-${detail.label}`}
                    value={draft[detail.key]}
                    onChange={(event) =>
                      setDraft((current) => ({
                        ...current,
                        [detail.key]: event.target.value,
                      }))
                    }
                    className="focus-visible:ring-2 focus-visible:ring-accent"
                    required={detail.key === "name"}
                  />
                ) : (
                  <Input
                    id={`profile-${detail.label}`}
                    value={detail.value}
                    readOnly
                    className="border-transparent bg-background font-medium text-foreground read-only:cursor-default"
                  />
                )}
              </div>
            ))}
          </div>
          {editing ? (
            <div className="mt-6 flex flex-wrap gap-3">
              <Button
                type="submit"
                disabled={saving}
                className="rounded-md bg-primary text-cream hover:bg-primary-dark"
              >
                <Check size={16} />
                {saving ? "Saving" : "Save"}
              </Button>
              <Button
                type="button"
                onClick={() => {
                  setDraft({ name: user.name, phone: user.phone ?? "" });
                  setEditing(false);
                }}
                className="rounded-md border border-border bg-transparent text-primary hover:bg-primary/5"
              >
                <X size={16} />
                Cancel
              </Button>
            </div>
          ) : null}
        </form>
      </section>

      <section className="mt-6 rounded-lg border border-border bg-card p-6 shadow-sm lg:p-8">
        <h2 className="font-heading text-lg font-bold text-primary">
          Security
        </h2>
        <div className="mt-4 flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between">
          <div>
            <p className="text-sm font-medium text-foreground">
              Change password
            </p>
            <p className="mt-1 text-sm text-muted">
              Update your password regularly to keep your account secure.
            </p>
          </div>
          <Button
            type="button"
            onClick={() => setPasswordOpen(true)}
            className="shrink-0 rounded-md border border-border bg-transparent text-primary hover:bg-primary/5"
          >
            <LockKeyhole size={16} />
            Change password
          </Button>
        </div>
      </section>

      <section className="mt-6 rounded-lg border border-red-200 bg-red-50/40 p-6 lg:p-8">
        <h2 className="font-heading text-lg font-bold text-red-700">
          Danger zone
        </h2>
        <div className="mt-3 flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between">
          <p className="text-sm text-red-700">
            Once you delete your account, there is no going back.
          </p>
          <button
            type="button"
            disabled
            title="Contact support to delete your account."
            className="
              min-h-10 cursor-not-allowed rounded-md bg-red-600 px-4
              text-sm font-medium text-white opacity-60
            "
          >
            Delete account
          </button>
        </div>
      </section>

      {passwordOpen ? (
        <PasswordDialog
          error={passwordError}
          passwords={passwords}
          saving={passwordSaving}
          onClose={() => {
            setPasswordOpen(false);
            setPasswordError("");
          }}
          onChange={setPasswords}
          onSubmit={changePassword}
        />
      ) : null}
    </div>
  );
}

function AvatarDisplay({
  avatarUrl,
  name,
}: {
  avatarUrl: string | null;
  name: string;
}) {
  if (avatarUrl) {
    return (
      <Image
        src={avatarUrl}
        alt={`${name}'s profile photo`}
        width={96}
        height={96}
        unoptimized
        className="h-24 w-24 rounded-full object-cover"
      />
    );
  }

  const initials = name
    .split(/\s+/)
    .filter(Boolean)
    .slice(0, 2)
    .map((part) => part[0]?.toUpperCase())
    .join("");

  return (
    <div
      aria-label={`${name} initials`}
      className="flex h-24 w-24 items-center justify-center rounded-full bg-primary font-heading text-3xl font-bold text-cream"
    >
      {initials || "?"}
    </div>
  );
}

function PasswordDialog({
  error,
  passwords,
  saving,
  onClose,
  onChange,
  onSubmit,
}: {
  error: string;
  passwords: {
    currentPassword: string;
    newPassword: string;
    confirmPassword: string;
  };
  saving: boolean;
  onClose: () => void;
  onChange: (value: typeof passwords) => void;
  onSubmit: (event: FormEvent<HTMLFormElement>) => void;
}) {
  return (
    <div className="fixed inset-0 z-[70] flex items-center justify-center bg-primary-dark/70 p-4">
      <button
        type="button"
        aria-label="Close password dialog"
        onClick={onClose}
        className="absolute inset-0 cursor-pointer focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-accent"
      />
      <section
        role="dialog"
        aria-modal="true"
        aria-labelledby="change-password-title"
        className="relative z-10 w-full max-w-md rounded-lg border border-border bg-card p-6 shadow-xl"
      >
        <div className="flex items-start justify-between gap-4">
          <div>
            <h2
              id="change-password-title"
              className="font-heading text-lg font-bold text-primary"
            >
              Change password
            </h2>
            <p className="mt-1 text-sm text-muted">
              Enter your current password and choose a new one.
            </p>
          </div>
          <button
            type="button"
            aria-label="Close dialog"
            onClick={onClose}
            className="cursor-pointer rounded p-1 text-muted focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-accent"
          >
            <X size={18} />
          </button>
        </div>
        <form onSubmit={onSubmit} className="mt-5 space-y-4">
          <PasswordField
            id="current-password"
            label="Current password"
            value={passwords.currentPassword}
            onChange={(currentPassword) =>
              onChange({ ...passwords, currentPassword })
            }
          />
          <PasswordField
            id="new-password"
            label="New password"
            value={passwords.newPassword}
            onChange={(newPassword) => onChange({ ...passwords, newPassword })}
          />
          <PasswordField
            id="confirm-password"
            label="Confirm new password"
            value={passwords.confirmPassword}
            onChange={(confirmPassword) =>
              onChange({ ...passwords, confirmPassword })
            }
          />
          {error ? (
            <p role="alert" className="text-sm text-red-600">
              {error}
            </p>
          ) : null}
          <div className="flex justify-end gap-3 pt-2">
            <Button
              type="button"
              onClick={onClose}
              className="rounded-md border border-border bg-transparent text-primary hover:bg-primary/5"
            >
              Cancel
            </Button>
            <Button
              type="submit"
              disabled={saving}
              className="rounded-md bg-primary text-cream hover:bg-primary-dark"
            >
              {saving ? "Saving" : "Save password"}
            </Button>
          </div>
        </form>
      </section>
    </div>
  );
}

function PasswordField({
  id,
  label,
  value,
  onChange,
}: {
  id: string;
  label: string;
  value: string;
  onChange: (value: string) => void;
}) {
  return (
    <div className="space-y-2">
      <Label htmlFor={id}>{label}</Label>
      <Input
        id={id}
        type="password"
        autoComplete="current-password"
        value={value}
        onChange={(event) => onChange(event.target.value)}
        required
        minLength={id === "current-password" ? undefined : 8}
        maxLength={72}
        className="focus-visible:ring-2 focus-visible:ring-accent"
      />
    </div>
  );
}

function formatDate(value: string) {
  return new Intl.DateTimeFormat("en", { dateStyle: "long" }).format(
    new Date(value),
  );
}

function getErrorMessage(error: unknown, fallback: string) {
  return error instanceof Error ? error.message : fallback;
}
